  function defaultStat(){return{attempts:0,correct:0,totalMs:0,streak:0,recent:[],mastery:0};}
  function defaultProgress(){var enabled={};CATEGORIES.forEach(function(c){enabled[c.id]=true;});return{version:1,view:"practice",settings:{adaptive:true,enabled:enabled},manual:{familyId:FAMILIES[0].id,level:1},stats:{}};}
  function mergeProgress(raw){var out=defaultProgress();if(!raw||typeof raw!=="object")return out;if(["practice","matrix","stats","settings","learn"].includes(raw.view))out.view=raw.view;if(raw.settings){out.settings.adaptive=raw.settings.adaptive!==false;CATEGORIES.forEach(function(c){if(raw.settings.enabled&&raw.settings.enabled[c.id]===false)out.settings.enabled[c.id]=false;});}if(raw.manual&&FAMILIES.some(function(f){return f.id===raw.manual.familyId;})){out.manual.familyId=raw.manual.familyId;out.manual.level=Math.max(1,Math.min(5,Number(raw.manual.level)||1));}if(raw.stats&&typeof raw.stats==="object")Object.keys(raw.stats).forEach(function(key){var x=raw.stats[key],p=key.split(":"),f=FAMILIES.find(function(y){return y.id===p[0];}),l=Number(p[1]);if(!x||!f||!f.levels.includes(l))return;out.stats[key]={attempts:Math.max(0,Number(x.attempts)||0),correct:Math.max(0,Number(x.correct)||0),totalMs:Math.max(0,Number(x.totalMs)||0),streak:Math.max(0,Number(x.streak)||0),recent:Array.isArray(x.recent)?x.recent.slice(-10).map(Boolean):[],mastery:Math.max(0,Math.min(100,Number(x.mastery)||0))};});return out;}
  function loadProgress(){return mergeProgress(PracticeLabUI.readJson(STORAGE_KEY,null));}function saveProgress(){PracticeLabUI.writeJson(STORAGE_KEY,progress);}function getStat(id,l){var key=id+":"+l;if(!progress.stats[key])progress.stats[key]=defaultStat();return progress.stats[key];}
