  function aggregate(){var z={attempts:0,correct:0,totalMs:0,practiced:0,masteryTotal:0};Object.values(progress.stats).forEach(function(s){z.attempts+=s.attempts;z.correct+=s.correct;z.totalMs+=s.totalMs;if(s.attempts){z.practiced++;z.masteryTotal+=s.mastery;}});return z;}
  function adaptiveCell(){var enabled=CATEGORIES.filter(function(c){return progress.settings.enabled[c.id]!==false;}).map(function(c){return c.id;});if(!enabled.length)enabled=CATEGORIES.map(function(c){return c.id;});var cells=[];FAMILIES.filter(function(f){return enabled.includes(f.categoryId);}).forEach(function(f){var levels=PracticeLabUI.unlockedLevels(f.levels,function(l){return getStat(f.id,l);}),l=levels[levels.length-1]||1,s=getStat(f.id,l);cells.push({family:f,level:l,score:(s.attempts?-s.mastery:-1000)+rng.int(0,18)});});cells.sort(function(a,b){return a.score-b.score;});return cells[rng.int(0,Math.min(3,cells.length-1))]||{family:FAMILIES[0],level:1};}
