  function collectAnswers(){var a={};document.querySelectorAll("[data-answer-field]").forEach(function(x){a[x.dataset.answerField]=x.value;});return a;}
  function submitAnswer(e){e.preventDefault();if(!currentQuestion||isPaused)return;if(submitted){startQuestion();return;}var result=checkQuestion(collectAnswers(),currentQuestion),duration=elapsedMs(),s=getStat(currentQuestion.familyId,currentQuestion.level);s.attempts++;s.correct+=result.correct?1:0;s.totalMs+=duration;s.streak=result.correct?s.streak+1:0;s.recent=s.recent.concat([result.correct]).slice(-10);updateMastery(s);saveProgress();submitted=true;document.querySelectorAll("[data-answer-field]").forEach(function(x){x.disabled=true;});updateKeypad();document.getElementById("submitBtn").innerHTML=PracticeLabUI.escapeHtml(t("practice.next","Next"))+' <span class="key-symbol">↵</span>';document.getElementById("nextBtn").classList.remove("hidden");document.getElementById("skipBtn").classList.add("hidden");keypadButtons.get("submit").textContent=t("practice.next","Next");var feedback=document.getElementById("feedback");feedback.className="feedback "+(result.correct?"correct":"incorrect");feedback.replaceChildren();var strong=document.createElement("strong");strong.textContent=result.correct?t("messages.correct","Correct"):t("messages.notQuite","Not quite");feedback.appendChild(strong);if(!result.correct){var expected=document.createElement("div");expected.className="expected-code";expected.textContent=t("messages.expected","Expected")+": "+result.expectedText;feedback.appendChild(expected);}var detail=document.createElement("div");detail.className="feedback-detail";detail.textContent=currentQuestion.explanation+" "+t("messages.time","Time")+": "+PracticeLabUI.formatSeconds(duration)+".";feedback.appendChild(detail);renderCurrentMetrics();renderSummary();}
  function pausePractice(){if(isPaused||submitted)return;stopAudio();isPaused=true;pauseStartedAt=Date.now();renderPauseState();}function resumePractice(){if(!isPaused)return;pausedMs+=Date.now()-pauseStartedAt;pauseStartedAt=0;isPaused=false;renderPauseState();}function renderPauseState(){var main=document.querySelector(".practice-main");if(main)main.classList.toggle("paused",isPaused);document.getElementById("pauseBtn").disabled=isPaused||submitted;updateKeypad();}
  function renderSummary(){var z=aggregate();document.getElementById("summaryMastery").textContent=(z.practiced?Math.round(z.masteryTotal/z.practiced):0)+"%";document.getElementById("summaryAccuracy").textContent=(z.attempts?Math.round(100*z.correct/z.attempts):0)+"%";document.getElementById("summaryAttempts").textContent=z.attempts;}
  function renderCurrentMetrics(){if(!currentQuestion)return;var s=getStat(currentQuestion.familyId,currentQuestion.level);document.getElementById("metricMastery").textContent=s.mastery+"%";document.getElementById("metricAccuracy").textContent=(s.attempts?Math.round(100*s.correct/s.attempts):0)+"%";document.getElementById("metricStreak").textContent=s.streak;document.getElementById("metricAvgTime").textContent=s.attempts?PracticeLabUI.formatSeconds(s.totalMs/s.attempts):"—";document.getElementById("questionMastery").textContent=s.mastery+"% "+t("practice.masterySuffix","mastery");}
  function renderPracticeControls(){document.getElementById("adaptiveModeBtn").classList.toggle("secondary-active",progress.settings.adaptive);document.getElementById("manualModeBtn").classList.toggle("secondary-active",!progress.settings.adaptive);if(selectorController)selectorController.render(currentQuestion?{familyId:currentQuestion.familyId,level:currentQuestion.level}:progress.manual);}
  function setManualSelection(id,l){progress.settings.adaptive=false;progress.manual.familyId=familyById(id).id;progress.manual.level=Math.max(1,Math.min(5,Number(l)||1));saveProgress();startQuestion();}
  function renderMatrix(){var c=document.getElementById("matrix");c.replaceChildren();var table=document.createElement("table"),head=document.createElement("thead"),hr=document.createElement("tr"),blank=document.createElement("th");blank.textContent=t("practice.family","Question family");hr.appendChild(blank);LEVELS.forEach(function(l){var th=document.createElement("th");th.textContent="L"+l;hr.appendChild(th);});head.appendChild(hr);table.appendChild(head);var body=document.createElement("tbody");CATEGORIES.forEach(function(cat){var cr=document.createElement("tr"),cc=document.createElement("th");cc.colSpan=6;cc.textContent=cat.title;cr.appendChild(cc);body.appendChild(cr);FAMILIES.filter(function(f){return f.categoryId===cat.id;}).forEach(function(f){var row=document.createElement("tr"),name=document.createElement("td");name.textContent=f.title;row.appendChild(name);LEVELS.forEach(function(l){var s=getStat(f.id,l),cell=document.createElement("td"),b=document.createElement("button");b.type="button";b.className="level-button "+(s.mastery>=80?"ready":s.attempts?"weak":"");b.dataset.familyId=f.id;b.dataset.level=l;b.innerHTML="L"+l+"<br><span>"+s.mastery+"% · "+s.attempts+"</span>";cell.appendChild(b);row.appendChild(cell);});body.appendChild(row);});});table.appendChild(body);c.appendChild(table);}
  function renderStats(){var z=aggregate();document.getElementById("statTotalAttempts").textContent=z.attempts;document.getElementById("statTotalCorrect").textContent=z.correct;document.getElementById("statTotalTime").textContent=PracticeLabUI.formatMinutes(z.totalMs);document.getElementById("statActiveCells").textContent=z.practiced;var cells=Object.keys(progress.stats).map(function(key){var p=key.split(":"),f=FAMILIES.find(function(x){return x.id===p[0];});return f?{family:f,level:Number(p[1]),stat:progress.stats[key]}:null;}).filter(function(x){return x&&x.stat.attempts;});cells.sort(function(a,b){return a.stat.mastery-b.stat.mastery;});function fill(id,items){var c=document.getElementById(id);c.replaceChildren();if(!items.length){var p=document.createElement("p");p.textContent=t("stats.noAttemptsYet","No attempts yet");c.appendChild(p);return;}items.forEach(function(x){var b=document.createElement("button");b.type="button";b.dataset.familyId=x.family.id;b.dataset.level=x.level;b.textContent=x.family.title+" · L"+x.level+" · "+x.stat.mastery+"% ("+x.stat.attempts+" "+t("stats.tries","tries")+")";c.appendChild(b);});}fill("weakList",cells.slice(0,8));fill("strongList",cells.slice().reverse().slice(0,8));}
  function renderSettings(){var c=document.getElementById("enabledCategories");c.replaceChildren();CATEGORIES.forEach(function(cat){var row=document.createElement("div"),label=document.createElement("label"),input=document.createElement("input"),span=document.createElement("span");row.className="check-row";input.type="checkbox";input.checked=progress.settings.enabled[cat.id]!==false;input.dataset.categoryId=cat.id;span.textContent=cat.title;label.append(input,span);row.appendChild(label);c.appendChild(row);});}
  function renderLearn(){var c=document.getElementById("learnGrid");c.replaceChildren();FAMILIES.forEach(function(f){var card=document.createElement("article"),h=document.createElement("h3"),p=document.createElement("p"),trap=document.createElement("p"),code=document.createElement("code");card.id="learn-"+f.id;card.className="learn-card"+(learnSpotlightId===f.id?" spotlight":"");h.textContent=f.title;p.textContent=f.learn.concept;trap.textContent=f.learn.rules;code.textContent=f.learn.example;card.append(h,p,trap,code);c.appendChild(card);});var credits=document.createElement("article"),h=document.createElement("h3"),p=document.createElement("p");credits.className="learn-card";h.textContent=t("audio.creditsTitle","Offline audio credits");p.textContent=Object.values(AUDIO_META).map(function(m){return m.speaker+" — "+m.license+" ("+m.source+")";}).join("; ");credits.append(h,p);c.appendChild(credits);}
  function setView(view){progress.view=view;saveProgress();document.querySelectorAll(".view").forEach(function(x){x.classList.toggle("active",x.id==="view-"+view);});document.querySelectorAll("[data-view]").forEach(function(x){x.classList.toggle("active",x.dataset.view===view);});if(view==="matrix")renderMatrix();if(view==="stats")renderStats();if(view==="settings")renderSettings();if(view==="learn"){renderLearn();if(learnSpotlightId){var card=document.getElementById("learn-"+learnSpotlightId);if(card)card.scrollIntoView({block:"center"});}}if(view==="practice"&&!currentQuestion)startQuestion();}
  function renderAll(){renderSummary();renderPracticeControls();renderMatrix();renderStats();renderSettings();renderLearn();setView(progress.view);}
  function wireEvents(){selectorController=PracticeLabUI.createPracticeSelectors({categorySelect:document.getElementById("categorySelect"),familySelect:document.getElementById("familySelect"),levelSelect:document.getElementById("levelSelect"),categories:CATEGORIES,families:FAMILIES,levelLabel:function(l){return t("practice.level","Level")+" "+l;},onSelect:function(s){setManualSelection(s.familyId,s.level);}});var editor=PracticeLabUI.createTextEditor(function(){return isPaused?null:activeAnswerInput;}),rows=[["は","が","を","に","で","へ","と"].map(function(ch){return[ch,editor.insert(ch),{id:"kana-"+ch}];}),["も","の","から","まで","より","っ","ー"].map(function(ch){return[ch,editor.insert(ch),{id:"kana-"+ch}];}),[["ゃ",editor.insert("ゃ"),{id:"kana-ya"}],["ゅ",editor.insert("ゅ"),{id:"kana-yu"}],["ょ",editor.insert("ょ"),{id:"kana-yo"}],[t("practice.delete","Del"),editor.backspace,{id:"delete",variant:"function",colspan:2}],[t("practice.clear","Clear"),editor.clear,{id:"clear",variant:"function",colspan:2}]],[[t("practice.check","Check"),function(){document.getElementById("answerForm").requestSubmit();},{id:"submit",variant:"primary",colspan:7}]]];keypadButtons=PracticeLabUI.renderInputGrid(document.getElementById("answerKeypad"),rows,{ariaLabel:t("practice.keypadAria","Japanese input helpers")});document.getElementById("answerKeypad").classList.add("kana-helper");document.querySelectorAll("[data-view]").forEach(function(b){b.addEventListener("click",function(){setView(b.dataset.view);});});document.getElementById("adaptiveModeBtn").addEventListener("click",function(){progress.settings.adaptive=true;saveProgress();startQuestion();});document.getElementById("manualModeBtn").addEventListener("click",function(){progress.settings.adaptive=false;saveProgress();startQuestion();});document.getElementById("pauseBtn").addEventListener("click",pausePractice);document.getElementById("resumeBtn").addEventListener("click",resumePractice);document.getElementById("learnCurrentBtn").addEventListener("click",function(){learnSpotlightId=currentQuestion.familyId;setView("learn");});document.getElementById("answerForm").addEventListener("submit",submitAnswer);document.getElementById("nextBtn").addEventListener("click",startQuestion);document.getElementById("skipBtn").addEventListener("click",startQuestion);document.getElementById("matrix").addEventListener("click",function(e){var b=e.target.closest("[data-family-id][data-level]");if(b){setView("practice");setManualSelection(b.dataset.familyId,b.dataset.level);}});["weakList","strongList"].forEach(function(id){document.getElementById(id).addEventListener("click",function(e){var b=e.target.closest("[data-family-id][data-level]");if(b){setView("practice");setManualSelection(b.dataset.familyId,b.dataset.level);}});});document.getElementById("enabledCategories").addEventListener("change",function(e){if(e.target.dataset.categoryId){progress.settings.enabled[e.target.dataset.categoryId]=e.target.checked;saveProgress();}});document.getElementById("exportBtn").addEventListener("click",function(){document.getElementById("dataBox").value=JSON.stringify(progress,null,2);});document.getElementById("copyBtn").addEventListener("click",function(){var box=document.getElementById("dataBox");if(!box.value)box.value=JSON.stringify(progress,null,2);PracticeLabUI.copyText(box.value);});document.getElementById("importBtn").addEventListener("click",function(){try{progress=mergeProgress(JSON.parse(document.getElementById("dataBox").value));saveProgress();currentQuestion=null;renderAll();}catch(e){document.getElementById("dataBox").value=t("messages.invalidJson","Invalid JSON")+": "+e.message;}});document.getElementById("resetBtn").addEventListener("click",function(){if(window.confirm(t("messages.resetConfirm","Reset all local progress?"))){progress=defaultProgress();saveProgress();currentQuestion=null;renderAll();}});document.addEventListener("keydown",function(e){if(e.key==="Enter"&&submitted&&progress.view==="practice"){e.preventDefault();startQuestion();}});}
  function runSelfTests(){var failures=[];function assert(ok,message){if(!ok&&failures.length<200)failures.push(message);}assert(CATEGORIES.length===6,"six categories");assert(FAMILIES.length===55,"all 55 families");assert(new Set(FAMILIES.map(function(f){return f.id;})).size===55,"unique families");assert(hira("カタカナ")==="かたかな"&&kata("ひらがな")==="ヒラガナ","script conversion");assert(morae("きって").join("|")==="き|っ|て"&&morae("きょう").join("|")==="きょ|う","mora segmentation");assert(romanize("きって")==="kitte"&&romanize("きょう")==="kyou","romanization");assert(verbForm("iku","te")==="行って"&&verbForm("kuru","nai")==="来ない"&&I_ADJ.ii.negativePast==="よくなかった","morphology exceptions");Object.keys(AUDIO_META).forEach(function(id){var m=AUDIO_META[id];assert(m.url&&m.url.indexOf("data:audio/ogg;base64,")===0,"embedded audio "+id);assert(m.transcript&&m.speaker&&m.license&&m.source,"audio attribution "+id);});if(TEXT.localeCode!=="en")assert(FAMILIES.every(function(f){var x=t("families."+f.id,null);return x&&x.title&&x.rule&&x.trap&&x.example;}),"complete translated families");FAMILIES.forEach(function(f,fi){assert(CASES[f.id]&&CASES[f.id].length>=3,"cases "+f.id);LEVELS.forEach(function(level){var signatures=new Set();for(var sample=0;sample<40;sample++){var seed=(fi+1)*100000+level*1000+sample+1;try{var q=generateQuestion(f.id,level,seed);assert(checkQuestion(q.canonicalAnswer,q).correct,"canonical "+f.id+":"+level);assert(!checkQuestion({},q).correct,"empty "+f.id+":"+level);assert(q.metadata.modelId===MODEL_ID&&q.metadata.dataVersion===DATA_VERSION,"metadata "+f.id);signatures.add(q.structuralSignature);}catch(e){failures.push(f.id+" L"+level+": "+e.message);}}assert(signatures.size>=2,"variation "+f.id+":"+level);});});if(failures.length){console.error("Japanese Language self-tests failed",failures);return{ok:false,failures:failures};}console.info("Japanese Language self-tests passed: 55 families, controlled Japanese model, offline human audio, 11,000 generated questions"+(TEXT.localeCode==="sv"?", complete Swedish content":""));return{ok:true,failures:[]};}
  function init(){progress=loadProgress();rng=new Rng((Date.now()^Math.floor(Math.random()*0xFFFFFFFF))>>>0);wireEvents();renderAll();}
  window.runSelfTests=runSelfTests;window.JapaneseLanguageApp={modelId:MODEL_ID,dataVersion:DATA_VERSION,oracleVersion:ORACLE_VERSION,categories:CATEGORIES,families:FAMILIES,generateQuestion:generateQuestion,checkQuestion:checkQuestion,runSelfTests:runSelfTests,oracles:{hira:hira,kata:kata,morae:morae,romanize:romanize,verbForm:verbForm,verbs:VERBS,adjectives:I_ADJ,audio:AUDIO_META}};document.addEventListener("DOMContentLoaded",init);
